components.css:
.ds-hatch-hotline__title, .ds-hatch-hotline__arrow, .ds-hatch-hotline-nav__button { background-color: transparent; border-width: 0; cursor: pointer; }
.ds-hatch-hotline__question { box-sizing: border-box; cursor: pointer; }
.ds-hatch-hotline {
  --hotline-ink: #302e2b;
  --hotline-muted: #77716c;
  --hotline-border: #ddd7d2;
  display: block;
  min-inline-size: 0;
  margin-block-start: 8px;
  padding: 18px;
  background: #f8efe9;
  color: var(--hotline-ink);
  font-family: "Circular Std", sans-serif;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  text-align: start;
}

.ds-hatch-hotline__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-block-size: 32px;
}

.ds-hatch-hotline__title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-block-size: 36px;
  margin-block: -4px;
  padding: 0;
  color: inherit;
  font: inherit;
  font-weight: 600;
  text-align: start;
}

.ds-hatch-hotline__icon {
  flex: 0 0 auto;
  color: #6e6964;
}

.ds-hatch-hotline__controls {
  display: flex;
  flex: 0 0 auto;
  gap: 4px;
  margin-inline-end: -8px;
}

.ds-hatch-hotline__arrow {
  display: grid;
  place-items: center;
  inline-size: 32px;
  block-size: 36px;
  margin-block: -4px;
  padding: 0;
  color: var(--hotline-muted);
}

.ds-hatch-hotline__arrow:disabled {
  opacity: 0.25;
  cursor: default;
}

.ds-hatch-hotline__description {
  margin: 12px 0 16px;
}

.ds-hatch-hotline__questions {
  display: flex;
  flex-wrap: nowrap;
  gap: 8px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
  padding: 3px;
  margin: -3px;
}

.ds-hatch-hotline__questions::-webkit-scrollbar {
  display: none;
}

.ds-hatch-hotline__question {
  flex: 0 0 auto;
  min-block-size: 44px;
  padding: 10px 13px;
  border: 1px solid var(--hotline-border);
  border-radius: 999px;
  background: #fff;
  color: inherit;
  font: inherit;
  white-space: nowrap;
  scroll-snap-align: start;
  transition: border-color 160ms ease-out, background-color 160ms ease-out;
}

.ds-hatch-hotline button:focus-visible,
.ds-hatch-hotline-nav__button:focus-visible {
  outline: 2px solid #302e2b;
  outline-offset: 2px;
}

.ds-hatch-hotline ::selection {
  background: #dfc2b2;
  color: #302e2b;
}

.ds-hatch-hotline-nav {
  margin-block-start: 12px;
  border-block: 1px solid #e3ded9;
}

.ds-hatch-hotline-nav__button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  inline-size: 100%;
  min-block-size: 56px;
  padding: 14px 0;
  color: #302e2b;
  font-family: "Circular Std", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: normal;
  text-align: start;
  text-transform: none;
}

.ds-hatch-hotline-nav__button .ds-hatch-hotline__icon {
  inline-size: 21px;
  block-size: 21px;
}

@media screen and (max-width: 699px) {
  .ds-hatch-hotline__question {
    padding-inline: 10px;
  }
}

@media (hover: hover) {
  .ds-hatch-hotline__question:hover {
    border-color: #a69a91;
    background: #fffaf7;
  }

  .ds-hatch-hotline__title:hover,
  .ds-hatch-hotline-nav__button:hover {
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  .ds-hatch-hotline__arrow:not(:disabled):hover {
    color: var(--hotline-ink);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-hatch-hotline__question {
    transition: none;
  }
}

